sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
 g_form.setReadOnly('u_year',false);
  if(g_form.getValue('state') != '10'){
	g_form.setReadOnly('activity_type',true);
	g_form.setReadOnly('department',true);
	g_form.setReadOnly('channel',true);
	g_form.setReadOnly('campaign',true);
	g_form.setReadOnly('main_expense',true);
	g_form.setReadOnly('activity',true);
	g_form.setReadOnly('product_category',true);
	g_form.setReadOnly('advertising_type',true);
	g_form.setReadOnly('sub_expense',true);
	g_form.setReadOnly('u_project_type',true);
	g_form.setReadOnly('u_number_range',true);
	g_form.setReadOnly('u_description',true);
	g_form.setReadOnly('u_total_budget',true);
   }
   else{
	g_form.setReadOnly('activity_type',false);
	g_form.setReadOnly('department',false);
	g_form.setReadOnly('channel',false);
	g_form.setReadOnly('campaign',false);
	g_form.setReadOnly('main_expense',false);
	g_form.setReadOnly('activity',false);
	g_form.setReadOnly('product_category',false);
	g_form.setReadOnly('advertising_type',false);
	g_form.setReadOnly('sub_expense',false);
	g_form.setReadOnly('u_project_type',false);
	g_form.setReadOnly('u_number_range',false);
	g_form.setReadOnly('u_description',false);
	g_form.setReadOnly('u_total_budget',false);
   }

}
